-- Kiss New York: Body Splash Dark Kiss 200ml
-- Preço de TESTE R$ 1,00 e ativo para venda (preço definitivo depois da reunião com o contador). Impostos em branco.
INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Kiss New York', true, 12, now(), now())
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "products" ("id", "sku", "name", "brandId", "description", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "internalNotes", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'KISS-BODY-SPLASH-DARK-KISS-200', 'Body Splash Dark Kiss 200ml', b."id",
       'Desodorante colônia com vitamina E • Notas de orquídea, bergamota e sândalo',
       'UN', 0, 0, 100, 0, 0, true,
       'PREÇO DE TESTE (R$ 1,00). Definir o preço real após a reunião com o contador.', now(), now()
  FROM "brands" b WHERE b."name" = 'Kiss New York'
ON CONFLICT ("sku") DO NOTHING;

INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'kiss-body-splash-dark-kiss-200.webp', 'image/webp', 23858, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'kiss-body-splash-dark-kiss-200.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'kiss-body-splash-dark-kiss-200.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'KISS-BODY-SPLASH-DARK-KISS-200' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
